  "rung_purposes": [
    {
      "rung": 1,
      "purpose": "Initialize test parameters (fill threshold, max pressure drop, and overpressure limit)."
    },
    {
      "rung": 2,
      "purpose": "Detect pack pressure transmitter wire break / out-of-range low fault (D100 < -500)."
    },
    {
      "rung": 3,
      "purpose": "Latch overpressure fault M291 when pack pressure exceeds limit D123."
    },
    {
      "rung": 4,
      "purpose": "Latch low supply air pressure fault M293 if supply switch X22 drops while busy."
    },
    {
      "rung": 5,
      "purpose": "Reset fill timeout, overpressure, and supply air faults on reset PB X1."
    },
    {
      "rung": 6,
      "purpose": "Consolidate alarm conditions and E-stop status into master trip M299 and beacon Y25."
    },
    {
      "rung": 7,
      "purpose": "Energize vent valve Y22 via manual vent pushbutton X25 when not in auto mode."
    },
    {
      "rung": 8,
      "purpose": "Initiate test cycle on pallet arrival in auto with no fault; clear results and set CLAMP."
    },
    {
      "rung": 9,
      "purpose": "Advance from CLAMP to FILL step when clamp closed switch X20 confirms clamp engagement."
    },
    {
      "rung": 10,
      "purpose": "Run 8.0s fill phase timeout timer T21 during FILL step."
    },
    {
      "rung": 11,
      "purpose": "Latch fill timeout alarm M290 when fill timer T21 expires."
    },
    {
      "rung": 12,
      "purpose": "Advance from FILL to STABILISE step once pack pressure reaches threshold D122."
    },
    {
      "rung": 13,
      "purpose": "Run 5.0s pressure stabilisation timer T22 during STABILISE step."
    },
    {
      "rung": 14,
      "purpose": "Sample initial test pressure into D110 when test window timer contact T23 is ON."
    },
    {
      "rung": 15,
      "purpose": "Advance from STABILISE to TEST step when stabilisation timer T22 completes."
    },
    {
      "rung": 16,
      "purpose": "Run 10.0s pressure decay test window timer T23 during TEST step."
    },
    {
      "rung": 17,
      "purpose": "Sample final pressure into D111 on T23 done and calculate pressure drop into D112."
    },
    {
      "rung": 18,
      "purpose": "Evaluate pressure drop D112 against limit D120 to set PASS (M210) or FAIL (M211)."
    },
    {
      "rung": 19,
      "purpose": "Advance from TEST to VENT step when test window timer T23 completes."
    },
    {
      "rung": 20,
      "purpose": "Abort active cycle on master fault M299, set FAIL result, and jump to VENT step."
    },
    {
      "rung": 21,
      "purpose": "Run vent timer T200 during VENT step."
    },
    {
      "rung": 22,
      "purpose": "Advance from VENT to UNCLAMP step when vented (T200 done, D100 < 1.00 kPa, sensor OK)."
    },
    {
      "rung": 23,
      "purpose": "Advance from UNCLAMP to COMPLETE step when clamp open switch confirms retracted."
    },
    {
      "rung": 24,
      "purpose": "Reset COMPLETE step and cycle busy flag M200 once pallet departs test position."
    },
    {
      "rung": 25,
      "purpose": "Energize clamp solenoid Y20 during CLAMP, FILL, STABILISE, TEST, and VENT steps."
    },
    {
      "rung": 26,
      "purpose": "Energize fill valve Y21 during FILL step if master fault M299 is clear."
    },
    {
      "rung": 27,
      "purpose": "Energize vent valve Y22 during VENT step or on overpressure fault M291."
    },
    {
      "rung": 28,
      "purpose": "Output PASS (Y23) or FAIL (Y24) signal to line controller during COMPLETE step."
    },
    {
      "rung": 29,
      "purpose": "End of main program scan."
    }
  ],
